def file_name_check(file_name):
    if file_name.count('.') != 1:
        return 'No'

    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    before_dot = parts[0]
    after_dot = parts[1]

    if not before_dot or not before_dot[0].isalpha():
        return 'No'

    if len([char for char in before_dot if char.isdigit()]) > 3:
        return 'No'

    if after_dot not in ['txt', 'exe', 'dll']:
        return 'No'

